mapper.select:
SELECT CASE WHEN EXISTS (
    SELECT 1 FROM dbo.Genre
    WHERE (Name = #{name} OR Slug = #{slug})
      AND GenreId <> #{exceptId}
) THEN 1 ELSE 0 END

mapper.update:
UPDATE dbo.Genre
Name = #{name}, Description = #{description, jdbcType=NVARCHAR}, SortOrder = #{sortOrder},
WHERE GenreId = #{genreId}

